import numpy as np

N = 6
board = np.zeros((N, N), dtype=int)
tromino_shape = [(0, 0), (1, 0), (0, 1)] # Relative coordinates: (r, c), (r+1, c), (r, c+1)

def can_place(r, c):
    """Checks if the tromino centered at (r, c) can be placed."""
    cells = [
        (r, c),
        (r + 1, c),
        (r, c + 1)
    ]
    if r + 1 >= N or c + 1 >= N:
        return False # Out of bounds check

    for rr, cc in cells:
        if board[rr, cc] != 0:
            return False # Overlap check
    return True

def place_tromino(r, c, value=1):
    """Places or removes a tromino."""
    cells = [
        (r, c),
        (r + 1, c),
        (r, c + 1)
    ]
    for rr, cc in cells:
        board[rr, cc] = value

def find_tiling():
    """Attempts to find a perfect tiling using backtracking."""

    # Find the first empty cell (r_start, c_start)
    def find_first_empty():
        for r in range(N):
            for c in range(N):
                if board[r, c] == 0:
                    return r, c
        return -1, -1

    def solve():
        r_start, c_start = find_first_empty()

        if r_start == -1:
            # Board is full, tiling successful
            return True

        # Try placing the tromino such that it covers (r_start, c_start).
        # Since the shape T(r, c) = {(r, c), (r+1, c), (r, c+1)} is fixed, 
        # the cell (r_start, c_start) must correspond to one of the 3 relative positions.

        # Case 1: (r_start, c_start) is the anchor (r, c)
        r, c = r_start, c_start
        if can_place(r, c):
            place_tromino(r, c, 1)
            if solve():
                return True
            place_tromino(r, c, 0) # Backtrack

        # Case 2: (r_start, c_start) is the bottom cell (r+1, c)
        r, c = r_start - 1, c_start
        if r >= 0 and can_place(r, c): # Check r-1 >= 0 for anchor r
            place_tromino(r, c, 1)
            if solve():
                return True
            place_tromino(r, c, 0) # Backtrack

        # Case 3: (r_start, c_start) is the right cell (r, c+1)
        r, c = r_start, c_start - 1
        if c >= 0 and can_place(r, c): # Check c-1 >= 0 for anchor c
            place_tromino(r, c, 1)
            if solve():
                return True
            place_tromino(r, c, 0) # Backtrack

        return False

    if solve():
        print("Tiling found.")
        # Output the placement positions (anchor points)
        placements = []
        for r in range(N):
            for c in range(N):
                if board[r, c] == 1 and (r, c) == (0, 0): # This is overly simplistic, need to enumerate anchors
                    pass

        # Easier to just iterate through the board and list covered cells
        for r in range(N):
            for c in range(N):
                if board[r, c] == 1:
                    placements.append((r, c))

        print(f"Board state:\n{board}")
        return True
    else:
        print("Tiling not found."
